import { REPARSE_HOST_PRIORITY, type ReparseHostsConfig } from '../dsl/wire/reparse-hosts.ts';

export function emitReparseHosts(config: ReparseHostsConfig | undefined): string | undefined {
	if (config === undefined) return undefined;
	const rows = Object.entries(config.hosts).map(([kind, template]) => `\t\t${JSON.stringify(kind)}: ${JSON.stringify(template)}`);
	return [
		'// Auto-generated by @sittir/codegen — do not edit',
		'',
		'export const REPARSE_HOSTS = {',
		'\thosts: {',
		rows.join(',\n'),
		'\t},',
		`\tpriority: ${JSON.stringify(config.priority ?? REPARSE_HOST_PRIORITY)},`,
		`\tgated: ${JSON.stringify(config.gated ?? [])}`,
		'} as const;',
		''
	].join('\n');
}
